mapper.select:
WITH RECURSIVE authorized_menu AS ( SELECT DISTINCT m.* FROM menu m JOIN role_menu rm ON m.menu_id = rm.menu_id JOIN user_role ur ON rm.role_id = ur.role_id WHERE ur.user_id = #{userId}
UNION DISTINCT
SELECT parent.* FROM menu parent JOIN authorized_menu child ON child.parent_id = parent.menu_id ) SELECT DISTINCT * FROM authorized_menu WHERE parent_id = #{parentId}
